import type { MetadataRoute } from "next";

// Web app manifest — makes the site installable ("Add to Home Screen") as a
// standalone PWA. Next serves this at /manifest.webmanifest and injects the
// <link rel="manifest"> automatically. Icons live in public/ (generated by
// scripts/generate-icons.mjs).
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Pixmoment — Chia sẻ ảnh chất lượng gốc",
    short_name: "Pixmoment",
    description: "Gửi ảnh cho nhau không mất một pixel nào. Chất lượng gốc 100%.",
    start_url: "/",
    display: "standalone",
    background_color: "#0a0a0f",
    theme_color: "#0a0a0f",
    lang: "vi",
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
